 1→// Package insightsdb provides a SQLite cache layer for session analytics.
 2→// It stores session metadata for fast querying by the insights and improve commands.
 3→package insightsdb
 4→
 5→import (
 6→	"context"
 7→	"database/sql"
 8→	"fmt"
 9→	"strings"
10→
11→	_ "modernc.org/sqlite" // SQLite driver
12→)
13→
14→// InsightsDB wraps a SQLite database for insights caching.
15→type InsightsDB struct {
16→	db *sql.DB
17→}
18→
19→// Open opens (or creates) the insights cache at the given path.
20→// It sets WAL mode and busy timeout for safe concurrent access,
21→// then runs migrations to ensure all tables exist.
22→func Open(dbPath string) (*InsightsDB, error) {
23→	db, err := sql.Open("sqlite", dbPath)
24→	if err != nil {
25→		return nil, fmt.Errorf("open sqlite database: %w", err)
26→	}
27→
28→	if err = applyPragmas(db); err != nil {
29→		_ = db.Close()
30→		return nil, err
31→	}
32→
33→	idb := &InsightsDB{db: db}
34→	if err = idb.migrate(); err != nil {
35→		_ = db.Close()
36→		return nil, fmt.Errorf("run migrations: %w", err)
37→	}
38→
39→	return idb, nil
40→}
41→
42→// applyPragmas sets performance and safety pragmas on the database.
43→func applyPragmas(db *sql.DB) error {
44→	ctx := context.Background()
45→	pragmas := []string{
46→		"PRAGMA journal_mode=WAL",
47→		"PRAGMA busy_timeout=5000",
48→	}
49→	for _, pragma := range pragmas {
50→		if _, err := db.ExecContext(ctx, pragma); err != nil {
51→			return fmt.Errorf("apply pragma %q: %w", pragma, err)
52→		}
53→	}
54→	return nil
55→}
56→
57→// Close closes the underlying database connection.
58→func (idb *InsightsDB) Close() error {
59→	if err := idb.db.Close(); err != nil {
60→		return fmt.Errorf("close insights database: %w", err)
61→	}
62→	return nil
63→}
