129→// querySessions executes a SELECT on sessions with the given args,
130→// then populates denormalized fields for each row.
131→func (idb *InsightsDB) querySessions(ctx context.Context, query string, args ...interface{}) ([]SessionRow, error) {
132→	rows, err := idb.db.QueryContext(ctx, query, args...)
133→	if err != nil {
134→		return nil, fmt.Errorf("query sessions: %w", err)
135→	}
136→	defer rows.Close()
137→
138→	var sessions []SessionRow
139→	for rows.Next() {
140→		row, err := scanSession(rows)
141→		if err != nil {
142→			return nil, err
143→		}
144→		sessions = append(sessions, row)
145→	}
146→	if err = rows.Err(); err != nil {
147→		return nil, fmt.Errorf("iterate sessions: %w", err)
148→	}
149→
150→	for i := range sessions {
151→		if err = idb.populateDenormalized(ctx, &sessions[i]); err != nil {
152→			return nil, err
153→		}
154→	}
155→	return sessions, nil
156→}
