158→// scanSession reads one row from the sessions table into a SessionRow.
159→func scanSession(rows *sql.Rows) (SessionRow, error) {
160→	var row SessionRow
161→	var createdAt string
162→	var agent, model, branch, ownerName, ownerEmail, intent, outcome sql.NullString
163→	var hasSummary, hasFacets int
164→
165→	err := rows.Scan(
166→		&row.CheckpointID, &row.SessionID, &row.SessionIndex,
167→		&agent, &model, &branch, &ownerName, &ownerEmail, &createdAt,
168→		&row.InputTokens, &row.CacheTokens, &row.OutputTokens, &row.TotalTokens,
169→		&row.APICallCount, &row.DurationMs, &row.TurnCount,
170→		&intent, &outcome, &row.AgentPct,
171→		&row.OverallScore, &row.ScoreTokenEff, &row.ScoreFirstPass,
172→		&row.ScoreFriction, &row.ScoreFocus, &hasSummary, &hasFacets,
173→	)
174→	if err != nil {
175→		return row, fmt.Errorf("scan session row: %w", err)
176→	}
177→
178→	row.Agent = agent.String
179→	row.Model = model.String
180→	row.Branch = branch.String
181→	row.OwnerName = ownerName.String
182→	row.OwnerEmail = ownerEmail.String
183→	row.Intent = intent.String
184→	row.Outcome = outcome.String
185→	row.HasSummary = hasSummary == 1
186→	row.HasFacets = hasFacets == 1
187→
188→	t, err := time.Parse(time.RFC3339, createdAt)
189→	if err != nil {
190→		return row, fmt.Errorf("parse created_at %q: %w", createdAt, err)
191→	}
192→	row.CreatedAt = t
193→	return row, nil
194→}
