104→// InsertSession inserts a session and all its denormalized data into the cache.
105→// The insert is performed inside a single transaction so the cache remains
106→// consistent even if the caller is interrupted mid-insert.
107→func (idb *InsightsDB) InsertSession(ctx context.Context, row SessionRow) error {
108→	tx, err := idb.db.BeginTx(ctx, nil)
109→	if err != nil {
110→		return fmt.Errorf("begin transaction: %w", err)
111→	}
112→	defer func() {
113→		if err != nil {
114→			_ = tx.Rollback() //nolint:errcheck // Rollback after failed tx; error is irrelevant
115→		}
116→	}()
117→
118→	if err = insertSessionRow(ctx, tx, row); err != nil {
119→		return err
120→	}
121→	if err = insertFilesTouched(ctx, tx, row); err != nil {
122→		return err
123→	}
124→	if err = insertFriction(ctx, tx, row); err != nil {
125→		return err
126→	}
127→	if err = insertLearnings(ctx, tx, row); err != nil {
128→		return err
129→	}
130→	if err = insertToolCalls(ctx, tx, row); err != nil {
131→		return err
132→	}
133→	if err = insertFacets(ctx, tx, row); err != nil {
134→		return err
135→	}
136→
137→	if err = tx.Commit(); err != nil {
138→		return fmt.Errorf("commit transaction: %w", err)
139→	}
140→	return nil
141→}
