143→func insertSessionRow(ctx context.Context, tx *sql.Tx, row SessionRow) error {
144→	hasSummary := 0
145→	if row.HasSummary {
146→		hasSummary = 1
147→	}
148→	hasFacets := 0
149→	if row.HasFacets || !isEmptyFacets(row.Facets) {
150→		hasFacets = 1
151→	}
152→	_, err := tx.ExecContext(ctx, `
153→		INSERT INTO sessions (
154→			checkpoint_id, session_id, session_index,
155→			agent, model, branch, owner_name, owner_email, created_at,
156→			input_tokens, cache_tokens, output_tokens, total_tokens,
157→			api_call_count, duration_ms, turn_count,
158→			intent, outcome, agent_percentage,
159→			overall_score, score_token_efficiency, score_first_pass,
160→			score_friction, score_focus, has_summary, has_facets
161→		) VALUES (
162→			?, ?, ?,
163→			?, ?, ?, ?, ?, ?,
164→			?, ?, ?, ?,
165→			?, ?, ?,
166→			?, ?, ?,
167→			?, ?, ?,
168→			?, ?, ?, ?
169→		)`,
170→		row.CheckpointID, row.SessionID, row.SessionIndex,
171→		nullableString(row.Agent), nullableString(row.Model), nullableString(row.Branch),
172→		nullableString(row.OwnerName), nullableString(row.OwnerEmail),
173→		row.CreatedAt.UTC().Format(time.RFC3339),
174→		row.InputTokens, row.CacheTokens, row.OutputTokens, row.TotalTokens,
175→		row.APICallCount, row.DurationMs, row.TurnCount,
176→		nullableString(row.Intent), nullableString(row.Outcome), row.AgentPct,
177→		row.OverallScore, row.ScoreTokenEff,
178→		row.ScoreFirstPass, row.ScoreFriction,
179→		row.ScoreFocus, hasSummary, hasFacets,
180→	)
181→	if err != nil {
182→		return fmt.Errorf("insert session row: %w", err)
183→	}
184→	return nil
185→}
