 12→var tabNames = [4]string{"Memories", "Injection", "History", "Settings"}
 13→
 14→func renderTabBar(s tuiStyles, activeTab int, width int, mode memoryloop.Mode, policy memoryloop.ActivationPolicy) string {
 15→	var b strings.Builder
 16→
 17→	// App title
 18→	b.WriteString(s.render(s.appTitle, "MEMORY LOOP"))
 19→	b.WriteString("   ")
 20→
 21→	// Track position for underline
 22→	titleWidth := len("MEMORY LOOP") + 3 // raw width of title + spacing
 23→	activeStart := 0
 24→	activeWidth := 0
 25→	pos := titleWidth
 26→
 27→	for i, name := range tabNames {
 28→		label := fmt.Sprintf("%d %s", i+1, name)
 29→		if i == activeTab {
 30→			activeStart = pos
 31→			activeWidth = len(label)
 32→			b.WriteString(s.render(s.tabActive, label))
 33→		} else {
 34→			b.WriteString(s.render(s.tabInactive, label))
 35→		}
 36→		pos += len(label)
 37→		if i < len(tabNames)-1 {
 38→			b.WriteString("   ")
 39→			pos += 3
 40→		}
 41→	}
 42→
 43→	// Right-align mode and policy indicators
 44→	left := b.String()
 45→	modeStr := s.render(s.active, fmt.Sprintf("● %s", mode))
 46→	policyStr := s.render(s.dim, fmt.Sprintf("· %s", policy))
 47→	right := modeStr + " " + policyStr
 48→
 49→	leftLen := lipglossWidth(left)
 50→	rightLen := lipglossWidth(right)
 51→	padding := width - leftLen - rightLen
 52→	if padding < 1 {
 53→		padding = 1
 54→	}
 55→
 56→	line1 := left + strings.Repeat(" ", padding) + right
 57→
 58→	// Underline row: amber ─ chars aligned under the active tab
 59→	line2 := strings.Repeat(" ", activeStart) +
 60→		s.render(s.tabUnderline, strings.Repeat("─", activeWidth))
 61→
 62→	return line1 + "\n" + line2
 63→}
